        "chapterNumber": 5,
        "verseNumber": 15,
        "text": "“If anyone commits a trespass, and sins unwittingly regarding Yahweh’s holy things, then he shall bring his trespass offering to Yahweh: a ram without defect from the flock, according to your estimation in silver by shekels, according to the shekel of the sanctuary, for a trespass offering.",
        "translation": "WEB",
