        "bookId": "LEV",
        "bookName": "Leviticus",
        "chapterNumber": 7,
        "verseNumber": 35,
        "text": "This is the consecrated portion of Aaron, and the consecrated portion of his sons, out of the offerings of Yahweh made by fire, in the day when he presented them to minister to Yahweh in the priest’s office;",
        "translation": "WEB",
