        "chapterNumber": 22,
        "verseNumber": 3,
        "text": "“Tell them, ‘If anyone of all your offspring throughout your generations approaches the holy things which the children of Israel make holy to Yahweh, having his uncleanness on him, that soul shall be cut off from before me. I am Yahweh.",
