        "bookName": "Leviticus",
        "chapterNumber": 22,
        "verseNumber": 4,
        "text": "“ ‘Whoever of the offspring of Aaron is a leper or has a discharge shall not eat of the holy things until he is clean. Whoever touches anything that is unclean by the dead, or a man who has a seminal emission,",
