        "verseNumber": 5,
        "text": "or whoever touches any creeping thing whereby he may be made unclean, or a man from whom he may become unclean, whatever uncleanness he has—",
        "translation": "WEB",
        "illustrationId": "ill-lev-22",
        "linkedEntities": []
