        "bookId": "LEV",
        "bookName": "Leviticus",
        "chapterNumber": 22,
        "verseNumber": 11,
        "text": "But if a priest buys a slave, purchased by his money, he shall eat of it; and those who are born in his house shall eat of his bread.",
