        "id": "LEV-22:21",
        "bookId": "LEV",
        "bookName": "Leviticus",
        "chapterNumber": 22,
        "verseNumber": 21,
        "text": "Whoever offers a sacrifice of peace offerings to Yahweh to accomplish a vow, or for a free will offering of the herd or of the flock, it shall be perfect to be accepted. It shall have no defect.",
