        "bookId": "LEV",
        "bookName": "Leviticus",
        "chapterNumber": 22,
        "verseNumber": 22,
        "text": "You shall not offer what is blind, is injured, is maimed, has a wart, is festering, or has a running sore to Yahweh, nor make an offering by fire of them on the altar to Yahweh.",
        "translation": "WEB",
