        "text": "“When a bull, a sheep, or a goat is born, it shall remain seven days with its mother. From the eighth day on it shall be accepted for the offering of an offering made by fire to Yahweh.",
        "translation": "WEB",
        "illustrationId": "ill-lev-22",
