        "bookName": "Leviticus",
        "chapterNumber": 23,
        "verseNumber": 38,
        "text": "in addition to the Sabbaths of Yahweh, and in addition to your gifts, and in addition to all your vows, and in addition to all your free will offerings, which you give to Yahweh.",
