        "bookId": "LEV",
        "bookName": "Leviticus",
        "chapterNumber": 23,
        "verseNumber": 40,
        "text": "You shall take on the first day the fruit of majestic trees, branches of palm trees, and boughs of thick trees, and willows of the brook; and you shall rejoice before Yahweh your God seven days.",
        "translation": "WEB",
        "illustrationId": "ill-lev-23",
